import { createContext } from '../../trpc/context'

/**
 * GET /api/architecture/admin
 *
 * The admin-only half of the generated API catalog (admin-level tRPC procedures,
 * the tables they touch, admin procedures referenced by stories). Kept out of
 * the public /architecture bundle on purpose; served only to an `is_admin`
 * dancer, using the same Bearer-session check as the tRPC adminProcedure.
 * Generated by scripts/architecture/generate.ts into server/assets.
 */
export default defineEventHandler(async (event) => {
  const ctx = await createContext({ req: toWebRequest(event) } as Parameters<typeof createContext>[0])
  if (!ctx.isAdmin) {
    throw createError({ statusCode: ctx.dancerId ? 403 : 401, statusMessage: 'Admin access required' })
  }
  setResponseHeader(event, 'Cache-Control', 'private, no-store')
  const data = await useStorage('assets:server').getItem('architecture:admin.json')
  if (!data) throw createError({ statusCode: 503, statusMessage: 'Architecture docs not generated' })
  return data
})
